import{_ as n,C as l,o as d,c as i,j as o,a as r,E as a,a2 as s}from"./chunks/framework.BSaF8iZ6.js";const k=JSON.parse('{"title":"Bulk Upload","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/bulk-upload.md","filePath":"catalog/bulk-upload.md","lastUpdated":1789411447000}'),c={name:"catalog/bulk-upload.md"};function h(p,t,u,g,m,w){const e=l("ImagePopup");return d(),i("div",null,[t[0]||(t[0]=o("h1",{id:"bulk-upload",tabindex:"-1"},[r("Bulk Upload "),o("a",{class:"header-anchor",href:"#bulk-upload","aria-label":'Permalink to "Bulk Upload"'},"​")],-1)),t[1]||(t[1]=o("div",{class:"page-roles"},[o("span",{class:"role role--seller"},"Seller")],-1)),t[2]||(t[2]=o("p",null,"Bulk upload adds many products at once from a spreadsheet. You can create your own new products, or sell products that are already in the store's catalog. The file is checked before anything is imported, and you get a report when it's done.",-1)),t[3]||(t[3]=o("p",null,[r("Go to "),o("strong",null,"Catalog >> Bulk Upload"),r(".")],-1)),a(e,{src:"/images/bulk-upload/imports.png",alt:"The Bulk Upload page with its two options and past uploads"}),t[4]||(t[4]=s('<h2 id="choose-what-to-upload" tabindex="-1">Choose what to upload <a class="header-anchor" href="#choose-what-to-upload" aria-label="Permalink to &quot;Choose what to upload&quot;">​</a></h2><ul><li><strong>List Your Own Products</strong> — create new products in your catalog.</li><li><strong>Sell Catalog Products</strong> — sell products that are already in the store&#39;s catalog, at your own price and stock.</li></ul><p>You see an option only when the store allows it and your role includes <strong>Bulk Upload &gt;&gt; Imports &gt;&gt; Create</strong>. Your profile must be complete.</p><p><strong>Past Uploads</strong> lists your earlier uploads with their type, state, file, completion time and a summary of what was created, updated or deleted. Use the row icons to <strong>Process</strong>, <strong>Edit</strong>, <strong>Download Report</strong> (a short summary of the run) or <strong>Delete</strong> an upload, and download the <strong>Error File</strong> when some rows failed.</p><h2 id="upload-a-file" tabindex="-1">Upload a file <a class="header-anchor" href="#upload-a-file" aria-label="Permalink to &quot;Upload a file&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Bulk Upload</strong>.</li><li>Click <strong>List Your Own Products</strong> or <strong>Sell Catalog Products</strong>.</li><li>In <strong>Source</strong>, under <strong>Download Sample</strong>, download the sample file in CSV, XLS, XLSX or XML.</li><li>Fill in your products using the sample&#39;s columns, then upload it in <strong>File</strong>.</li><li>Click <strong>Next</strong>.</li><li>For your own products, choose in <strong>Images</strong> how the images reach the store, then click <strong>Next</strong>.</li><li>In <strong>Settings</strong>, check the options below.</li><li>Click <strong>Start Import</strong>, then confirm.</li></ol>',6)),a(e,{src:"/images/bulk-upload/create-source.png",alt:"The Source step of the bulk upload wizard"}),t[5]||(t[5]=s('<h3 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h3><ul><li><strong>Image URLs in the sheet</strong> — add public links to the images, separated by commas, in the <code>images</code> column. The store downloads them for you. This is the recommended option.</li><li><strong>Upload a ZIP of images</strong> — put the image file names in the <code>images</code> column and upload one ZIP file that contains them. The store sets the largest ZIP you can upload, 10 MB unless it has changed it.</li></ul><p>Products you sell from the catalog use the catalog&#39;s images, so this step doesn&#39;t appear for them.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Action</strong></td><td><strong>Create/Update</strong> adds new products and updates existing ones. <strong>Delete</strong> removes the products in the file. For catalog products, it removes only your offers.</td></tr><tr><td><strong>Validation Strategy</strong></td><td><strong>Stop on Errors</strong> blocks the import when the file has more errors than <strong>Allowed Errors</strong>. Up to that number, the bad rows are skipped and the rest are imported. <strong>Skip Errors</strong> skips every bad row and imports the rest.</td></tr><tr><td><strong>Allowed Errors</strong></td><td>Used only with <strong>Stop on Errors</strong>: the most errors the file can have and still be imported. Starts at 10.</td></tr><tr><td><strong>Field Separator</strong></td><td>The character between columns in a CSV file, usually a comma.</td></tr><tr><td><strong>Process in Background</strong></td><td>Keeps the import running after you leave the page. It appears when the store can run imports in the background.</td></tr></tbody></table><h2 id="check-and-run-the-import" tabindex="-1">Check and run the import <a class="header-anchor" href="#check-and-run-the-import" aria-label="Permalink to &quot;Check and run the import&quot;">​</a></h2><p>The <strong>Import</strong> page opens and checks your file straight away. When the check finishes, it shows the <strong>Total Rows Processed</strong>, <strong>Total Invalid Rows</strong> and <strong>Total Errors</strong>.</p><ul><li><strong>Every row is valid</strong> — the import starts on its own.</li><li><strong>Some rows have errors, and your settings allow them to be skipped</strong> — the page lists the errors and says the remaining rows can still be imported. Click <strong>Start Import</strong> to import them.</li><li><strong>The file is invalid</strong> — fix the errors and upload the file again.</li></ul><p>Click <strong>Download Full Report</strong> to download every error with its row.</p><p>The page shows each stage as it runs, with the progress and the number of batches completed. For your own products, the images are downloaded, the products are created, related products are linked and prices and stock are finalized. For catalog products, the offers are added to your shop.</p><p>When it finishes, you&#39;ll see <strong>Congratulations! Your import was successful.</strong> with how many products were created, updated or deleted. Click <strong>Back</strong> to see them in <strong>Catalog &gt;&gt; Products</strong>.</p>',11)),a(e,{src:"/images/bulk-upload/import-complete.png",alt:"A completed import with its summary"}),t[6]||(t[6]=s('<p>New imported products follow the store&#39;s approval rules like any other product. To change a product that is already approved, edit it in the product form rather than importing it again. See <a href="./product-approval">Product Approval</a>.</p><h2 id="what-goes-in-the-file" tabindex="-1">What goes in the file <a class="header-anchor" href="#what-goes-in-the-file" aria-label="Permalink to &quot;What goes in the file&quot;">​</a></h2><h3 id="your-own-products" tabindex="-1">Your own products <a class="header-anchor" href="#your-own-products" aria-label="Permalink to &quot;Your own products&quot;">​</a></h3><p>Start from the sample file. It has a column for each product detail, including <code>sku</code>, <code>type</code>, <code>attribute_family_code</code>, <code>categories</code>, <code>images</code>, <code>name</code>, <code>description</code>, <code>price</code>, <code>weight</code>, <code>status</code>, <code>inventories</code> and, for products with variations, <code>configurable_variants</code>.</p><ul><li>A SKU another seller already uses can&#39;t be imported.</li><li>Each product type must be one you are allowed to sell.</li><li>Downloadable products can&#39;t be imported. Create them one at a time in the product form.</li><li>Each image link can be up to 10 MB.</li></ul><h3 id="catalog-products" tabindex="-1">Catalog products <a class="header-anchor" href="#catalog-products" aria-label="Permalink to &quot;Catalog products&quot;">​</a></h3><p>The sheet has five columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>What to enter</th></tr></thead><tbody><tr><td><code>sku</code></td><td>The catalog product&#39;s SKU. Required.</td></tr><tr><td><code>price</code></td><td>Your price. Leave it empty to use the catalog price.</td></tr><tr><td><code>qty</code></td><td>How many you have in stock. It goes into your first active inventory source.</td></tr><tr><td><code>condition</code></td><td><code>new</code> or <code>old</code>. Leave it empty for <code>new</code>.</td></tr><tr><td><code>description</code></td><td>A description of your offer. Optional.</td></tr></tbody></table><p>A row fails when no catalog product has the SKU, when you already sell it, when the SKU appears twice in the file, when the store doesn&#39;t allow sellers to sell catalog products, when you aren&#39;t allowed to sell that product type, or when <code>price</code>, <code>qty</code> or <code>condition</code> has an invalid value.</p><h2 id="change-or-rerun-an-upload" tabindex="-1">Change or rerun an upload <a class="header-anchor" href="#change-or-rerun-an-upload" aria-label="Permalink to &quot;Change or rerun an upload&quot;">​</a></h2><p>Click the edit icon on an upload in <strong>Past Uploads</strong>, replace the file or change the settings, then click <strong>Reimport</strong> and confirm. The file is checked again from the start.</p><p>If the store uses subscription plans, products over your plan&#39;s limit aren&#39;t imported.</p>',12))])}const y=n(c,[["render",h]]);export{k as __pageData,y as default};
